import{z as n,x as A,o as t,c as B,q as i,j as l,D as m,d as E,s,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"胶的 γ 与对比度","description":"","frontmatter":{"title":"胶的 γ 与对比度","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/resist-gamma.md","filePath":"litho/resist-gamma.md","lastUpdated":1791413859000}'),p={name:"litho/resist-gamma.md"};function d(h,a,g,D,C,_){const r=A("Mermaid");return t(),B("div",null,[a[2]||(a[2]=i('<h1 id="胶的-γ-与对比度" tabindex="-1">胶的 γ 与对比度 <a class="header-anchor" href="#胶的-γ-与对比度" aria-label="Permalink to &quot;胶的 γ 与对比度&quot;">​</a></h1><div class="epigraph"><p>光学对比度问空中像亮暗差了多少；胶的 $\\gamma$ 问对数剂量变一点，剩余厚度掉多陡。两个词不能互换。</p><footer>—— 据 Mack 对显影衬度 $\\gamma$ 与光学对比 $C$ 的区分整理</footer></div><p><a href="/litho/resist-profile-simulation">上一课</a>在三维里切出浮雕。缺口是把产线常说的「胶对比度」收回一个数：均匀曝光垫上剩余厚度对 \\(\\log E\\) 的陡度 \\(\\gamma\\)。主干<a href="/litho/resist-contrast-curve">衬度曲线</a>已经定义过它。本课补的差是：与 Dill / RD / \\(R(m)\\) 链的关系，以及为何不能跟空中像 \\(C\\)、NILS 混名。两个剂量锚点 \\(E_0\\) 与 \\(E_\\mathrm{size}\\)，留给<a href="/litho/e0-esize">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>大垫实验没有衍射图形，剩余厚度 \\(T(E)\\) 只反映材料与显影时间。中段</p> \\[\\gamma \\sim \\left|\\frac{d(T/T_0)}{d\\ln E}\\right| \\]<p>是胶的规格语言。光学 \\(C=(I_\\mathrm{max}-I_\\mathrm{min})/(I_\\mathrm{max}+I_\\mathrm{min})\\) 在<a href="/litho/aerial-image-contrast">空中像对比度</a>里，对象是 \\(I(x)\\)。把「这层对比不够」说成胶 \\(\\gamma\\) 低，可能其实是照明让 \\(C\\) 掉了。</p><p>轮廓仿真在横向有结构时给出侧壁；\\(\\gamma\\) 是同一套 \\(R(m)\\) 在无结构极限的读出。\\(R(m)\\) 越开关，\\(\\gamma\\) 越大。缺口是让后课引用「胶对比度」时默认指 \\(\\gamma\\)，不是 \\(C\\)。</p><p><span class="marginnote">术语翻译：\\(\\gamma\\) 回答「剂量的对数每变一点，剩余厚度掉多陡」，是胶自己的规格；光学 \\(C\\) 回答「空中像亮处比暗处亮多少」，是光的规格。线印不好时先分清该怪谁——把照明造成的低 \\(C\\) 错怪成胶 \\(\\gamma\\) 低，就会花钱换胶而不动照明，白忙一场。</span></p><h3 id="γ-过大同样有害" tabindex="-1">γ 过大同样有害 <a class="header-anchor" href="#γ-过大同样有害" aria-label="Permalink to &quot;γ 过大同样有害&quot;">​</a></h3><p>极陡的 \\(\\gamma\\) 把剂量噪声和 LWR 切成台阶。主干已经警告。接到本课链上：Notch 很深、\\(n\\) 很大、中和面很薄，都会抬 \\(\\gamma\\)，同时抬边缘对计数噪声的增益。随机单元会把这句话变成缺陷率；本课先记下「\\(\\gamma\\) 不是越大越好」。</p><p><span class="marginnote">报 \\(\\gamma\\) 必须声明胶厚、是否去驻波、PEB 与显影时间。带 swing 的曲线斜率不是材料本征 \\(\\gamma\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实验：开口板剂量矩阵，固定显影，测 \\(T(\\log E)\\)。从曲线同时读出后课要用的 \\(E_0\\)（开始掉厚或清场，定义要写清）以及本课的中段斜率。模拟：关掉横向变化，只跑 \\(z\\) 向 Dill + RD + \\(R\\)，应能复现这条曲线——这是对 ABC 与 \\(R(m)\\) 联合标定的检查。复现不了大垫，就不要信图形上的轮廓仿真。</p><p><span class="marginnote">直觉类比：无图形大垫实验像「关掉所有干扰源，单独测麦克风的灵敏度」——没有衍射、没有邻居线、没有驻波结构，读出来的才是胶自己的陡度。连这个干净极限都复现不了的仿真，图形版结果更不能信。</span></p><p>与 NILS：曝光宽容度大致随光学 NILS 与胶 \\(\\gamma\\) 同向变，但公式系数依赖如何切 CD。本课不把 EL 写完，只禁止用 \\(\\gamma\\) 替代 NILS。</p>',16)),(t(),l(o,null,{default:m(()=>[s(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22R(m)%22%5D%20--%3E%20PAD%5B%22%E5%A4%A7%E5%9E%AB%20T(log%20E)%22%5D%0A%20%20PAD%20--%3E%20GAMMA%5B%22%CE%B3%20%E4%B8%AD%E6%AE%B5%E9%99%A1%E5%BA%A6%22%5D%0A%20%20C%5B%22%E7%A9%BA%E4%B8%AD%E5%83%8F%20C%22%5D%20--%3E%20NILS%5B%22NILS%22%5D%0A%20%20GAMMA%20--%3E%20EL%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%89%82%E9%87%8F%E9%94%9A%E7%82%B9%22%5D%0A%20%20NILS%20--%3E%20EL%0A"})]),fallback:m(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"\\(m\\) 随剂量经 \\(C\\) 与 PEB 下降；\\(R(m)\\) 的非线性把缓变的 \\(m\\) 变成陡变的剩余厚度。Dill \\(A\\) 漂白会让厚胶的 \\(T(E)\\) 形状扭曲，因为沿 \\(z\\) 的有效剂量不均匀——看起来像 \\(\\gamma\\) 在变，其实是吸收在变。CAR 的 \\(\\gamma\\) 对 PEB 极敏感：催化不足时曲线变钝，过催化时暗区泄漏把肩抬起来。",-1)),a[5]||(a[5]=e("p",null,"光学对比 \\(C\\) 再高，若 \\(\\gamma\\) 钝，显影切不狠；\\(\\gamma\\) 再陡，若 \\(C\\) 为零级偏置抬死，也没有剂量间隔可切。两者相乘，不是可替换。",-1)),(t(),l(o,null,{default:m(()=>[s(r,{id:"mermaid-54",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E7%A9%BA%E4%B8%AD%E5%83%8F%E5%AF%B9%E6%AF%94%20C%22%5D%20--%3E%20PROD%7B%22%E7%9B%B8%E4%B9%98%E6%89%8D%E5%8F%AF%E5%8D%B0%22%7D%0A%20%20G%5B%22%E8%83%B6%E9%99%A1%E5%BA%A6%20%CE%B3%22%5D%20--%3E%20PROD%0A%20%20PROD%20--%3E%7C%22C%20%E9%AB%98%20%CE%B3%20%E9%92%9D%22%7C%20DULL%5B%22%E6%98%BE%E5%BD%B1%E5%88%87%E4%B8%8D%E7%8B%A0%EF%BC%8C%E8%BE%B9%E7%B3%8A%22%5D%0A%20%20PROD%20--%3E%7C%22C%20%E4%BD%8E%20%CE%B3%20%E9%99%A1%22%7C%20BIAS%5B%22%E5%81%8F%E7%BD%AE%E6%8A%AC%E6%AD%BB%EF%BC%8C%E6%97%A0%E5%89%82%E9%87%8F%E9%97%B4%E9%9A%94%E5%8F%AF%E5%88%87%22%5D%0A%20%20DULL%20--%3E%20EL%5B%22%E5%8F%AF%E5%8D%B0%E7%AA%97%E5%8F%A3%20%3D%20C%20%E4%B8%8E%20%CE%B3%20%E8%81%94%E5%90%88%E5%86%B3%E5%AE%9A%22%5D%0A%20%20BIAS%20--%3E%20EL%0A"})]),fallback:m(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<p><span class="marginnote">常见误区：初学者容易以为厚胶测出的 \\(\\gamma\\) 偏低是「这瓶胶不行」。其实是 Dill 漂白让沿厚度方向的剂量不均匀、曲线形状被吸收扭曲——同一瓶胶，厚薄不同读数就不同。这属于光学叠层问题，不该写进显影模型的本征陡度。</span></p><p><span class="marginnote">负胶曲线上下翻转，\\(\\gamma\\) 仍取绝对值陡度。不要把「负」理解成另一种光学 \\(C\\)。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不重推 \\(\\gamma\\) 的每一种教材定义变体；产线对表时写明用的是哪一种归一化。不把数据表 \\(\\gamma=12\\) 抄到所有层。下一课把曲线上的两个剂量点命名为 \\(E_0\\) 与 \\(E_\\mathrm{size}\\)，斜率 \\(\\gamma\\) 已经假定可测。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>胶 \\(\\gamma\\) 是大垫 \\(T(\\log E)\\) 的陡度；光学 \\(C\\) / NILS 是空中像的量。</li><li>\\(\\gamma\\) 来自 \\(R(m)\\) 与 RD，可用无图形仿真复现来做标定检查。</li><li>过陡放大噪声；报 \\(\\gamma\\) 必须声明厚、PEB、驻波。</li><li>下一课用同一条曲线上的剂量锚点。</li><li>出处：Mack 对 \\(\\gamma\\) 与 \\(C\\) 的区分；主干<a href="/litho/resist-contrast-curve">衬度曲线</a>。</li></ul>',6))])}const u=n(p,[["render",d]]);export{f as __pageData,u as default};
